#!/bin/sh
# Plain chats of the web UI run in ~/chats (the "Chats" project): there the storage rules, environment and tool map
# load up front (CLAUDE.md generated by the session-start hook) and the prompt cache lives 1 hour, because storage
# work pauses to read results. Code projects get only the core ~/.claude/CLAUDE.md and the API key's 5-minute cache.
# usage: setup-chats.sh <session-start.py>   (run as the account itself; safe to run again)
set -eu
mkdir -p "$HOME/chats/.claude"
python3 - "$HOME/chats/.claude/settings.json" <<'EOP' || echo "left $HOME/chats/.claude/settings.json as it is (not valid JSON)"
import json, os, sys
p = sys.argv[1]
s = json.load(open(p)) if os.path.exists(p) else {}
if "promptCacheTtl" not in s:
    s["promptCacheTtl"] = "1h"
    json.dump(s, open(p, "w"), indent=2)
EOP
python3 "$1" </dev/null >/dev/null || true          # writes ~/chats/CLAUDE.md now, not at the first chat
